package com.barrowsbrothersrandomizer;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;

/** Client-thread-only classic rig evidence. Prepared outside animate(); bounded loads and caches, no reflection. */
final class AnimationRigCache
{
	private static final int MAX_LOADS_PER_TICK = 24;
	private final Client client;
	private final Cache<Integer, Sequence> sequences = CacheBuilder.newBuilder().maximumSize(256).build();
	private final Cache<Long, Rig> frames = CacheBuilder.newBuilder().maximumSize(2048).build();
	private final Cache<Integer, Rig> skeletons = CacheBuilder.newBuilder().maximumSize(256).build();
	private final Cache<Long, Integer> misses = CacheBuilder.newBuilder().maximumSize(2048).build();
	private int tick = Integer.MIN_VALUE, loads;

	AnimationRigCache(Client client) { this.client = client; }

	Compatibility compare(int nativeSequence, int action)
	{
		Sequence own = sequence(nativeSequence), borrowed = sequence(action);
		if (!own.complete() || !borrowed.complete()) { return Compatibility.UNKNOWN; }
		return own.rigs.containsAll(borrowed.rigs) ? Compatibility.COMPATIBLE : Compatibility.INCOMPATIBLE;
	}

	enum Compatibility { COMPATIBLE, INCOMPATIBLE, UNKNOWN }

	private Sequence sequence(int id)
	{
		if (id < 0) { return Sequence.invalid(); }
		Sequence entry = sequences.getIfPresent(id);
		if (entry == null)
		{
			// Current schema only. Old revisions have different sound/Maya opcode payloads.
			if (client.getRevision() < 226) { return Sequence.invalid(); }
			byte[] bytes = load(2, 12, id); // CONFIGS / SEQUENCE
			if (bytes == null) { return Sequence.invalid(); }
			entry = decode(bytes);
			sequences.put(id, entry);
		}
		if (entry.invalid || entry.complete() || entry.lastAttempt == client.getTickCount()) { return entry; }
		entry.lastAttempt = client.getTickCount();
		while (entry.next < entry.frames.length)
		{
			int frame = entry.frames[entry.next];
			long key = frame & 0xffffffffL;
			Rig rig = frames.getIfPresent(key);
			if (rig == null)
			{
				byte[] bytes = load(0, frame >>> 16, frame & 65535); // ANIMATIONS
				if (bytes == null) { break; }
				if (bytes.length < 3) { entry.invalid = true; break; }
				int skeleton = (bytes[0] & 255) << 8 | bytes[1] & 255;
				rig = skeletons.getIfPresent(skeleton);
				if (rig == null)
				{
					byte[] map = load(1, skeleton, 0); // SKELETONS
					if (map == null) { break; }
					rig = Rig.decode(map);
					skeletons.put(skeleton, rig);
				}
				if (!rig.invalid && !validFrame(bytes, rig.types.length)) { rig = Rig.invalid(); }
				frames.put(key, rig);
			}
			if (rig.invalid) { entry.invalid = true; break; }
			entry.rigs.add(rig);
			entry.next++;
		}
		return entry;
	}

	private byte[] load(int index, int archive, int file)
	{
		int now = client.getTickCount();
		if (tick != now) { tick = now; loads = 0; }
		long key = ((long) index << 56) | ((long) archive << 24) | file;
		Integer missed = misses.getIfPresent(key);
		if (loads >= MAX_LOADS_PER_TICK || (missed != null && missed == now)) { return null; }
		loads++;
		try
		{
			IndexDataBase database = index == 2 ? client.getIndexConfig() : client.getIndex(index);
			byte[] bytes = database == null ? null : database.loadData(archive, file);
			if (bytes == null) { misses.put(key, now); }
			return bytes;
		}
		catch (RuntimeException ex) { misses.put(key, now); return null; }
	}

	private static Sequence decode(byte[] bytes)
	{
		ByteBuffer data = ByteBuffer.wrap(bytes);
		int[] references = null;
		try
		{
			while (data.hasRemaining())
			{
				int opcode = u8(data);
				switch (opcode)
				{
					case 0: return references == null || references.length == 0 ? Sequence.invalid() : new Sequence(references);
					case 1:
						int count = u16(data);
						if (count > 4096) { return Sequence.invalid(); }
						skip(data, count * 2);
						references = new int[count];
						for (int i = 0; i < count; i++) { references[i] = u16(data); }
						for (int i = 0; i < count; i++) { references[i] |= u16(data) << 16; }
						break;
					case 2: case 6: case 7: skip(data, 2); break;
					case 3: skip(data, u8(data)); break;
					case 4: case 19: break;
					case 5: case 8: case 9: case 10: case 11: case 16: skip(data, 1); break;
					case 12: skip(data, u8(data) * 4); break;
					case 13: return Sequence.invalid(); // Maya/weighted: no automatic borrowing.
					case 14: skip(data, u16(data) * 8); break; // frame ushort + modern sound's six bytes
					case 15: skip(data, 4); break;
					case 17: skip(data, u8(data)); break;
					case 18: while (data.get() != 0) { /* Skip the sequence name. */ } break;
					default: return Sequence.invalid();
				}
			}
		}
		catch (RuntimeException malformed) { return Sequence.invalid(); }
		return Sequence.invalid();
	}

	private static boolean validFrame(byte[] bytes, int transforms)
	{
		try
		{
			int count = bytes[2] & 255;
			if (count > transforms || bytes.length < 3 + count) { return false; }
			ByteBuffer values = ByteBuffer.wrap(bytes); values.position(3 + count);
			for (int i = 0; i < count; i++)
			{
				int flags = bytes[3 + i] & 255;
				if ((flags & ~7) != 0) { return false; }
				for (int bit = 1; bit <= 4; bit <<= 1)
				{
					if ((flags & bit) != 0) { skip(values, (values.get(values.position()) & 128) == 0 ? 1 : 2); }
				}
			}
			return !values.hasRemaining();
		}
		catch (RuntimeException malformed) { return false; }
	}
	private static int u8(ByteBuffer data) { return data.get() & 255; }
	private static int u16(ByteBuffer data) { return data.getShort() & 65535; }
	private static void skip(ByteBuffer data, int count)
	{
		if (count > data.remaining()) { throw new IllegalArgumentException(); }
		data.position(data.position() + count);
	}
	void clear() { sequences.invalidateAll(); frames.invalidateAll(); skeletons.invalidateAll(); misses.invalidateAll(); tick = Integer.MIN_VALUE; }

	private static final class Sequence
	{
		final int[] frames;
		final Set<Rig> rigs = new HashSet<>();
		boolean invalid;
		int next, lastAttempt = Integer.MIN_VALUE;
		Sequence(int[] frames) { this.frames = frames; }
		static Sequence invalid() { Sequence s = new Sequence(new int[0]); s.invalid = true; return s; }
		boolean complete() { return !invalid && next == frames.length && !rigs.isEmpty(); }
	}

	private static final class Rig
	{
		final int[] types;
		final int[][] labels;
		final boolean invalid;
		Rig(int[] types, int[][] labels, boolean invalid) { this.types = types; this.labels = labels; this.invalid = invalid; }
		static Rig invalid() { return new Rig(new int[0], new int[0][], true); }
		static Rig decode(byte[] bytes)
		{
			try
			{
				ByteBuffer data = ByteBuffer.wrap(bytes);
				int count = u8(data);
				int[] types = new int[count]; int[][] labels = new int[count][];
				for (int i = 0; i < count; i++)
				{
					types[i] = u8(data);
					if (types[i] > 3 && types[i] != 5) { return invalid(); }
				}
				int totalLabels = 0;
				for (int i = 0; i < count; i++)
				{
					int length = u8(data); totalLabels += length;
					if (totalLabels > 4096) { return invalid(); }
					labels[i] = new int[length];
				}
				boolean geometry = false;
				for (int i = 0; i < count; i++)
				{
					for (int j = 0; j < labels[i].length; j++) { labels[i][j] = u8(data); }
					geometry |= types[i] >= 1 && types[i] <= 3 && labels[i].length > 0;
				}
				if (data.hasRemaining() && (data.remaining() != 2 || u16(data) != 0)) { return invalid(); }
				if (!geometry) { return invalid(); }
				return new Rig(types, labels, false);
			}
			catch (RuntimeException malformed) { return invalid(); }
		}
		@Override public int hashCode() { return 31 * Arrays.hashCode(types) + Arrays.deepHashCode(labels); }
		@Override public boolean equals(Object other)
		{
			if (!(other instanceof Rig)) { return false; }
			Rig rig = (Rig) other;
			return Arrays.equals(types, rig.types) && Arrays.deepEquals(labels, rig.labels);
		}
	}
}

package com.barrowsbrothersrandomizer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BarrowsBrothersRandomizerConfig.GROUP)
public interface BarrowsBrothersRandomizerConfig extends Config
{
	String GROUP = "barrowsbrothersrandomizer";

	@Range(min = 0, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(keyName = "chanceToRandomize", name = "Chance to randomize", position = 0,
		description = "Chance per brother spawn to receive a random NPC disguise. 0% keeps originals; 100% always randomizes. Changes affect future spawns only.")
	default int chanceToRandomize() { return 100; }

	@ConfigItem(keyName = "npcAnimationMode", name = "NPC animation mode", position = 1,
		description = "Native: native gait only. Auto: borrow brother actions only with classic rig evidence. Force: try brother actions even on unknown rigs. No mode filters NPC IDs.")
	default NpcAnimationMode npcAnimationMode() { return NpcAnimationMode.AUTO; }
}

package com.barrowsbrothersrandomizer;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Barrows Brothers Randomizer",
	description = "Give each Barrows brother a random NPC disguise while preserving combat and interactions",
	tags = {"barrows", "brothers", "random", "npc", "disguise"})
public class BarrowsBrothersRandomizerPlugin extends Plugin
{
	static final int CRYPT_REGION = 14231;
	private static final String LEGACY_GROUP = "barrowsthemes";
	private static final String INTERIM_GROUP = "barrowsbrothersrandomnpc";
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private RenderCallbackManager renderCallbacks;
	@Inject private BarrowsBrothersRandomizerConfig config;
	@Inject private ConfigManager configManager;
	private volatile boolean active;
	private final BrotherDisguises disguises = new BrotherDisguises();
	private final RenderCallback disguiseListener = new RenderCallback()
	{
		// Scene admission and mouse picking still use the original NPC. Suppress only
		// its later GPU geometry upload after a visual disguise is successfully active.
		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			if (!active || !(object instanceof GameObject)) { return true; }
			Renderable renderable = ((GameObject) object).getRenderable();
			return !(renderable instanceof NPC) || !disguises.hides((NPC) renderable);
		}
	};

	@Provides
	BarrowsBrothersRandomizerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(BarrowsBrothersRandomizerConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateConfig(configManager);
		active = true;
		renderCallbacks.register(disguiseListener);
		clientThread.invokeLater(() -> { if (active) { refreshDisguises(); } });
	}

	/** Carry over NPC settings only; never import the removed theme/texture/recording options. */
	static void migrateConfig(ConfigManager manager)
	{
		if (manager == null) { return; }
		String group = BarrowsBrothersRandomizerConfig.GROUP;
		manager.unsetConfiguration(group, "nativeNpcAttacks");
		manager.unsetConfiguration(group, "npcActionOverrides");
		if (Boolean.parseBoolean(manager.getConfiguration(group, "migratedLegacyNpcSettings"))) { return; }
		String[] keys = {"npcAnimationMode"};
		String sourceGroup = LEGACY_GROUP;
		if (Boolean.parseBoolean(manager.getConfiguration(INTERIM_GROUP, "migratedLegacyNpcSettings"))) { sourceGroup = INTERIM_GROUP; }
		for (String key : keys)
		{
			if (manager.getConfiguration(INTERIM_GROUP, key) != null) { sourceGroup = INTERIM_GROUP; break; }
		}
		for (String key : keys)
		{
			if (manager.getConfiguration(group, key) != null) { continue; }
			String saved = manager.getConfiguration(sourceGroup, key);
			if (saved != null) { manager.setConfiguration(group, key, saved); }
		}
		if (LEGACY_GROUP.equals(sourceGroup) && manager.getConfiguration(group, "npcAnimationMode") == null
			&& Boolean.parseBoolean(manager.getConfiguration(LEGACY_GROUP, "brotherAttackAnimations")))
		{
			manager.setConfiguration(group, "npcAnimationMode", NpcAnimationMode.FORCE);
		}
		manager.unsetConfiguration(LEGACY_GROUP, "brotherAttackAnimations");
		manager.unsetConfiguration(LEGACY_GROUP, "recordNpcActions");
		manager.setConfiguration(group, "migratedLegacyNpcSettings", true);
	}

	@Override
	protected void shutDown()
	{
		active = false;
		renderCallbacks.unregister(disguiseListener);
		clientThread.invoke(disguises::clear);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BarrowsBrothersRandomizerConfig.GROUP.equals(event.getGroup()))
		{
			// Preserve per-spawn chance rolls and selections; update animation options in place.
			clientThread.invokeLater(() -> { if (active) { refreshDisguises(); } });
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN) { disguises.clear(); }
	}

	@Subscribe
	public void onGameTick(GameTick event) { refreshDisguises(); }

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (active && client.getGameState() == GameState.LOGGED_IN) { disguises.move(); }
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (active && client.getGameState() == GameState.LOGGED_IN && event.getActor() instanceof NPC)
		{
			disguises.actionChanged((NPC) event.getActor());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (active && client.getGameState() == GameState.LOGGED_IN && eligibleBrother(event.getNpc()))
		{
			disguises.spawn(client, event.getNpc(), config.chanceToRandomize());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event) { disguises.despawn(event.getNpc()); }

	private boolean eligibleBrother(NPC npc)
	{
		return BrotherDisguises.isBrother(npc.getId()) && npc.getWorldView() != null
			&& npc.getLocalLocation() != null
			&& WorldPoint.fromLocalInstance(npc.getWorldView().getScene(), npc.getLocalLocation(),
				npc.getWorldView().getPlane()).getRegionID() == CRYPT_REGION;
	}

	private void refreshDisguises()
	{
		if (!active || client.getGameState() != GameState.LOGGED_IN || client.getTopLevelWorldView() == null)
		{
			disguises.clear();
			return;
		}
		List<NPC> eligible = new ArrayList<>();
		for (NPC npc : client.getNpcs()) { if (eligibleBrother(npc)) { eligible.add(npc); } }
		disguises.refresh(client, eligible, config.npcAnimationMode(), config.chanceToRandomize());
	}
}

package com.barrowsbrothersrandomizer;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;

/** Optional action layer synchronized to the real brother, not independently looped. */
final class BrotherActionAnimation extends AnimationController
{
	private final Client client;
	private final NPC brother;
	private final Set<Integer> unsupported = new HashSet<>();
	private final Set<Integer> attempted = new HashSet<>();
	private final Cache<Integer, Animation> loaded = CacheBuilder.newBuilder().maximumSize(32).build();
	private int action = -1;
	private int attemptTick = Integer.MIN_VALUE;

	BrotherActionAnimation(Client client, NPC brother)
	{
		super(client, (Animation) null);
		this.client = client; this.brother = brother;
	}

	@Override
	public void tick(int ticks) { /* Playback belongs to the real NPC. */ }

	/** Discover/load actions outside rendering, with at most one attempt per action per game tick. */
	void prepare()
	{
		int id = brother.getAnimation();
		if (id != action)
		{
			action = id;
			setAnimation(null);
		}
		if (id < 0 || unsupported.contains(id)) { return; }
		int tick = client.getTickCount();
		if (attemptTick != tick) { attemptTick = tick; attempted.clear(); }
		if (getAnimation() == null)
		{
			try
			{
				Animation animation = loaded.getIfPresent(id);
				if (animation == null && attempted.add(id)) { animation = client.loadAnimation(id); }
				if (animation != null) { loaded.put(id, animation); setAnimation(animation); }
			}
			catch (RuntimeException ex) { fail(id); }
		}
	}

	@Override
	public Model animate(Model model, AnimationController other)
	{
		int id = brother.getAnimation();
		if (id < 0 || id != action || unsupported.contains(id)) { return model; }
		try
		{
			Animation animation = getAnimation();
			int frame = brother.getAnimationFrame();
			if (animation == null || frame < 0 || frame >= animation.getNumFrames()) { return model; }
			Model animated = client.applyTransformations(model, animation, frame, null, 0);
			return animated != null ? animated : model;
		}
		catch (RuntimeException ex)
		{
			fail(id);
			return model;
		}
	}

	private void fail(int id)
	{
		unsupported.add(id);
		setAnimation(null);
	}
}

package com.barrowsbrothersrandomizer;

import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Collections;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.IntUnaryOperator;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.gameval.NpcID;

/** Visual-only, per-spawn disguises. Never mutates NPC definitions or original models. */
final class BrotherDisguises
{
	// NPC definitions are files in config archive 9 (RuneLite cache ConfigType.NPC).
	// There is no corresponding config-archive constant in the public client API.
	private static final int NPC_ARCHIVE = 9;
	private int[] npcIds;
	private final Map<NPC, Disguise> disguises = new IdentityHashMap<>();
	private final IntUnaryOperator random;
	private AnimationRigCache rigs;

	BrotherDisguises() { this(bound -> ThreadLocalRandom.current().nextInt(bound)); }
	BrotherDisguises(IntUnaryOperator random) { this.random = random; }

	static boolean isBrother(int id)
	{
		switch (id)
		{
			case NpcID.BARROWS_AHRIM:
			case NpcID.BARROWS_DHAROK:
			case NpcID.BARROWS_GUTHAN:
			case NpcID.BARROWS_KARIL:
			case NpcID.BARROWS_TORAG:
			case NpcID.BARROWS_VERAC: return true;
			default: return false;
		}
	}

	void spawn(Client client, NPC npc, int chance)
	{
		if (!isBrother(npc.getId())) { return; }
		Disguise disguise = disguises.computeIfAbsent(npc, ignored -> new Disguise());
		if (!disguise.chanceRolled)
		{
			disguise.chanceRolled = true;
			int percent = Math.max(0, Math.min(100, chance));
			disguise.randomize = percent == 100 || (percent > 0 && random.applyAsInt(100) < percent);
		}
		if (!disguise.randomize || disguise.source >= 0) { return; }
		if (npcIds == null)
		{
			IndexDataBase configs = client.getIndexConfig();
			int[] ids = configs == null ? null : configs.getFileIds(NPC_ARCHIVE);
			if (ids == null || ids.length == 0) { return; }
			npcIds = ids.clone();
		}
		// Sample every available ID equally, without size, name, animation or rig filters.
		disguise.source = npcIds[random.applyAsInt(npcIds.length)];
	}

	/** Also discovers brothers already present when the plugin is enabled. */
	void refresh(Client client, List<NPC> eligible, NpcAnimationMode mode, int chance)
	{
		if (rigs == null) { rigs = new AnimationRigCache(client); }
		Set<NPC> present = Collections.newSetFromMap(new IdentityHashMap<>());
		present.addAll(eligible);
		for (NPC npc : eligible) { spawn(client, npc, chance); }
		Iterator<Map.Entry<NPC, Disguise>> iterator = disguises.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<NPC, Disguise> entry = iterator.next();
			if (!present.contains(entry.getKey()))
			{
				remove(entry.getValue());
				iterator.remove();
				continue;
			}
			Disguise disguise = entry.getValue();
			if (disguise.object != null)
			{
				disguise.controller.options(mode);
				disguise.controller.prepare();
				continue;
			}
			if (disguise.source < 0) { continue; }
			RuneLiteObject staged = null;
			try
			{
				LoadedModel model = load(client, disguise);
				if (model == null) { continue; } // Retry this same choice, never reroll on cache misses.
				staged = client.createRuneLiteObject();
				staged.setModel(model.model);
				NativeNpcAnimation controller = new NativeNpcAnimation(client, entry.getKey(), model.definitionId, rigs, mode);
				controller.prepare();
				staged.setAnimationController(controller);
				staged.setRadius(60);
				place(staged, entry.getKey());
				staged.setActive(true);
				if (!staged.isActive()) { staged.setActive(false); continue; }
				disguise.object = staged;
				disguise.controller = controller;
			}
			catch (RuntimeException ex)
			{
				if (staged != null) { deactivate(staged); }
			}
		}
	}

	private LoadedModel load(Client client, Disguise disguise)
	{
		NPCComposition definition = client.getNpcDefinition(disguise.source);
		if (definition == null) { return null; }
		int definitionId = disguise.source;
		if (definition.getConfigs() != null)
		{
			definition = definition.transform();
			if (definition == null) { return null; }
			definitionId = definition.getId();
		}
		int[] ids = definition.getModels();
		if (ids == null || ids.length == 0) { return null; }
		ModelData[] parts = new ModelData[ids.length];
		for (int i = 0; i < ids.length; i++)
		{
			parts[i] = client.loadModelData(ids[i]);
			if (parts[i] == null) { return null; }
		}
		ModelData data = (parts.length == 1 ? parts[0] : client.mergeModels(parts))
			.shallowCopy().cloneVertices().cloneColors();
		short[] from = definition.getColorToReplace();
		short[] to = definition.getColorToReplaceWith();
		if (from != null && to != null)
		{
			for (int i = 0; i < Math.min(from.length, to.length); i++) { data.recolor(from[i], to[i]); }
		}
		data.scale(definition.getWidthScale(), definition.getHeightScale(), definition.getWidthScale());
		data.translate(0, 0, 0); // Invalidate copied normals after scaling.
		Model model = data.light();
		if (model == null) { return null; }
		return new LoadedModel(model, definitionId);
	}

	void actionChanged(NPC npc)
	{
		Disguise disguise = disguises.get(npc);
		if (disguise != null && disguise.controller != null) { disguise.controller.actionChanged(); }
	}

	void move()
	{
		for (Map.Entry<NPC, Disguise> entry : disguises.entrySet())
		{
			Disguise disguise = entry.getValue();
			if (disguise.object == null) { continue; }
			try { disguise.controller.prepare(); place(disguise.object, entry.getKey()); }
			catch (RuntimeException ex)
			{
				remove(disguise);
			}
		}
	}

	private void place(RuneLiteObject object, NPC npc)
	{
		object.setLocation(npc.getLocalLocation(), npc.getWorldView().getPlane());
		object.setOrientation(npc.getCurrentOrientation());
	}

	boolean hides(NPC npc)
	{
		Disguise disguise = disguises.get(npc);
		return disguise != null && disguise.object != null && disguise.object.isActive();
	}

	void despawn(NPC npc)
	{
		Disguise disguise = disguises.remove(npc);
		if (disguise != null) { remove(disguise); }
	}

	void clear()
	{
		for (Disguise disguise : disguises.values()) { remove(disguise); }
		disguises.clear();
		npcIds = null;
		if (rigs != null) { rigs.clear(); rigs = null; }
	}

	private void remove(Disguise disguise)
	{
		if (disguise.object != null) { deactivate(disguise.object); disguise.object = null; }
	}

	private void deactivate(RuneLiteObject object)
	{
		try { object.setActive(false); }
		catch (RuntimeException ignored) { /* Continue cleanup of the remaining disguises. */ }
	}

	private static final class LoadedModel
	{
		final Model model;
		final int definitionId;
		LoadedModel(Model model, int definitionId) { this.model = model; this.definitionId = definitionId; }
	}

	private static final class Disguise
	{
		private boolean chanceRolled;
		private boolean randomize;
		private int source = -1;
		private NativeNpcAnimation controller;
		private RuneLiteObject object;
	}
}

package com.barrowsbrothersrandomizer;

import com.google.common.base.Preconditions;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.Model;
import net.runelite.api.NPC;

/** Native gait plus evidence-gated brother actions. Never changes the real actor. */
final class NativeNpcAnimation extends AnimationController
{
	private final Client client;
	private final NPC brother;
	private final int sourceId;
	private final BrotherActionAnimation brotherActions;
	private final AnimationRigCache rigs;
	private final Map<Integer, Animation> loaded = new HashMap<>();
	private final Set<Integer> unsupported = new HashSet<>();
	private final Set<Integer> attempted = new HashSet<>();
	private NativeNpcAnimations sequences;
	private NpcAnimationMode mode;
	private int metadataAttempt = Integer.MIN_VALUE, attemptTick = Integer.MIN_VALUE;
	private int preparedTick = Integer.MIN_VALUE, preparedAction = -1, preparedSequence = -1;
	private boolean compatible;
	private int selected = -1;

	NativeNpcAnimation(Client client, NPC brother, int sourceId, AnimationRigCache rigs, NpcAnimationMode mode)
	{
		super(client, (Animation) null);
		this.client = client; this.brother = brother; this.sourceId = sourceId; this.rigs = rigs;
		brotherActions = new BrotherActionAnimation(client, brother);
		options(mode);
	}

	void options(NpcAnimationMode mode)
	{
		Preconditions.checkNotNull(mode, "Animation mode");
		if (this.mode == mode) { return; }
		this.mode = mode;
		preparedTick = Integer.MIN_VALUE; preparedAction = -1; compatible = false;
	}

	void actionChanged() { preparedTick = Integer.MIN_VALUE; compatible = false; }

	private void metadata()
	{
		int tick = client.getTickCount();
		if (sequences == null && metadataAttempt != tick)
		{
			metadataAttempt = tick;
			IndexDataBase configs = client.getIndexConfig();
			byte[] data = configs == null ? null : configs.loadData(9, sourceId);
			if (data != null) { sequences = NativeNpcAnimations.decode(data); }
		}
	}

	/** Called on client/game/animation ticks, never from rendering. */
	void prepare()
	{
		try
		{
			metadata();
			prepareGait();
			int action = brother.getAnimation(), tick = client.getTickCount();
			if (action != preparedAction || tick != preparedTick || selected != preparedSequence)
			{
				preparedAction = action; preparedTick = tick; preparedSequence = selected; compatible = false;
				compatible = mode == NpcAnimationMode.AUTO && action >= 0
					&& sequences != null && sequences.complete()
					&& rigs.compare(selected, action) == AnimationRigCache.Compatibility.COMPATIBLE;
			}
			if (borrow()) { brotherActions.prepare(); }
		}
		catch (RuntimeException ex)
		{
			compatible = false;
		}
	}

	private boolean borrow()
	{
		int action = brother.getAnimation();
		if (action < 0 || mode == NpcAnimationMode.NATIVE) { return false; }
		return mode == NpcAnimationMode.FORCE
			|| (preparedAction == action && preparedTick == client.getTickCount()
				&& preparedSequence == currentGait() && compatible);
	}

	private int currentGait() { return sequences == null ? -1 : sequences.sequenceFor(brother); }

	private void prepareGait()
	{
		int id = currentGait();
		if (id != selected) { selected = id; setAnimation(null); }
		if (id < 0 || unsupported.contains(id) || getAnimation() != null) { return; }
		int tick = client.getTickCount();
		if (attemptTick != tick) { attemptTick = tick; attempted.clear(); }
		Animation animation = loaded.get(id);
		if (animation == null && attempted.add(id)) { animation = client.loadAnimation(id); }
		if (animation != null) { loaded.put(id, animation); setAnimation(animation); }
	}

	@Override public void tick(int ticks)
	{
		try
		{
			prepare(); super.tick(ticks);
		}
		catch (RuntimeException ex) { fallback(); }
	}

	@Override public Model animate(Model model, AnimationController other)
	{
		try
		{
			if (borrow())
			{
				Model action = brotherActions.animate(model, null);
				if (action != model) { return action; }
			}
			// A changed pose waits for tick-owned preparation instead of discovering assets here.
			if (selected != currentGait()) { return model; }
			Animation animation = getAnimation();
			if (animation == null || getFrame() < 0 || getFrame() >= animation.getNumFrames()) { return model; }
			Model animated = super.animate(model, null);
			return animated != null ? animated : model;
		}
		catch (RuntimeException ex) { fallback(); return model; }
	}

	private void fallback()
	{
		if (selected >= 0) { unsupported.add(selected); }
		setAnimation(null);
	}
}

package com.barrowsbrothersrandomizer;

import java.nio.ByteBuffer;
import net.runelite.api.NPC;

/** Best-effort sequence metadata from config archive 9; no meshes or cache files are opened. */
final class NativeNpcAnimations
{
	private static final NativeNpcAnimations EMPTY = new NativeNpcAnimations();
	private boolean complete;
	boolean complete() { return complete; }
	private NativeNpcAnimations() { }
	private int idle = -1, walk = -1, back = -1, left = -1, right = -1, turnLeft = -1, turnRight = -1, run = -1;
	private int runBack = -1, runLeft = -1, runRight = -1, crawl = -1, crawlBack = -1, crawlLeft = -1, crawlRight = -1;

	static NativeNpcAnimations decode(byte[] bytes)
	{
		NativeNpcAnimations result = new NativeNpcAnimations();
		ByteBuffer data = ByteBuffer.wrap(bytes);
		try
		{
			while (data.hasRemaining())
			{
				int opcode = u8(data);
				switch (opcode)
				{
					case 0: result.complete = true; return result;
					case 1: case 60: skip(data, u8(data) * 2); break;
					case 61: case 62: skip(data, u8(data) * 4); break;
					case 2: case 30: case 31: case 32: case 33: case 34: string(data); break;
					case 12: case 100: case 101: skip(data, 1); break;
					case 13: result.idle = sequence(data); break;
					case 14: result.walk = sequence(data); break;
					case 15: result.turnLeft = sequence(data); break;
					case 16: result.turnRight = sequence(data); break;
					case 17:
						result.walk = sequence(data); result.back = sequence(data);
						result.left = sequence(data); result.right = sequence(data); break;
					case 18: case 74: case 75: case 76: case 77: case 78: case 79:
					case 95: case 97: case 98: case 103: case 124: case 126: case 146: skip(data, 2); break;
					case 40: case 41: skip(data, u8(data) * 4); break;
					case 93: case 99: case 107: case 109: case 111: case 122: case 123:
					case 129: case 130: case 145: case 147: break;
					case 102:
						int mask = u8(data);
						for (int bit = 0; bit < 8; bit++)
						{
							if ((mask & 1 << bit) == 0) { continue; }
							skip(data, (data.get(data.position()) & 128) != 0 ? 4 : 2);
							skip(data, (data.get(data.position()) & 128) != 0 ? 2 : 1);
						}
						break;
					case 106: case 118:
						skip(data, opcode == 118 ? 6 : 4);
						skip(data, (u8(data) + 1) * 2); break;
					case 114: result.run = sequence(data); break;
					case 115:
						result.run = sequence(data); result.runBack = sequence(data);
						result.runLeft = sequence(data); result.runRight = sequence(data); break;
					case 116: result.crawl = sequence(data); break;
					case 117:
						result.crawl = sequence(data); result.crawlBack = sequence(data);
						result.crawlLeft = sequence(data); result.crawlRight = sequence(data); break;
					case 249:
						int count = u8(data);
						for (int i = 0; i < count; i++)
						{
							boolean text = u8(data) == 1;
							skip(data, 3);
							if (text) { string(data); } else { skip(data, 4); }
						}
						break;
					case 251: skip(data, 2); string(data); break;
					case 252: skip(data, 13); string(data); break;
					case 253: skip(data, 15); string(data); break;
					// Never scan unknown payload bytes as opcodes. Keep only the known prefix.
					default:
						return result;
				}
			}
		}
		catch (RuntimeException malformed) { return EMPTY; }
		return EMPTY; // Missing terminator/truncated metadata is not trusted.
	}

	int sequenceFor(NPC brother)
	{
		int pose = brother.getPoseAnimation();
		if (pose < 0 || pose == brother.getIdlePoseAnimation()) { return idle; }
		int moving = fallback(walk, fallback(crawl, fallback(run, idle)));
		if (pose == brother.getRunAnimation()) { return fallback(run, moving); }
		if (pose == brother.getIdleRotateLeft()) { return fallback(turnLeft, idle); }
		if (pose == brother.getIdleRotateRight()) { return fallback(turnRight, idle); }
		if (pose == brother.getWalkRotate180()) { return fallback(back, fallback(crawlBack, fallback(runBack, moving))); }
		if (pose == brother.getWalkRotateLeft()) { return fallback(left, fallback(crawlLeft, fallback(runLeft, moving))); }
		if (pose == brother.getWalkRotateRight()) { return fallback(right, fallback(crawlRight, fallback(runRight, moving))); }
		return moving;
	}

	private static int fallback(int preferred, int backup) { return preferred >= 0 ? preferred : backup; }
	private static int u8(ByteBuffer data) { return data.get() & 255; }
	private static int sequence(ByteBuffer data) { int id = data.getShort() & 65535; return id == 65535 ? -1 : id; }
	private static void string(ByteBuffer data) { while (data.get() != 0) { /* Skip a cache string. */ } }
	private static void skip(ByteBuffer data, int count)
	{
		if (count > data.remaining()) { throw new IllegalArgumentException("Truncated NPC metadata"); }
		data.position(data.position() + count);
	}
}

