package com.barrowsbrothersrandomizer;

import java.util.Collections;
import java.util.List;
import java.util.ArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.NpcID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BrotherDisguisesTest
{
	private Client client;
	private NPC brother;
	private BrotherDisguises disguises;
	private final BarrowsBrothersRandomizerConfig defaults = new BarrowsBrothersRandomizerConfig() { };
	private final AtomicInteger picks = new AtomicInteger();
	private final List<RuneLiteObject> objects = new ArrayList<>();
	private ModelData original;
	private ModelData detached;

	@Before
	public void setup()
	{
		client = mock(Client.class);
		IndexDataBase configs = mock(IndexDataBase.class);
		when(client.getIndexConfig()).thenReturn(configs);
		when(configs.getFileIds(9)).thenReturn(new int[] {NpcID.CHICKEN, NpcID.COW});
		brother = mock(NPC.class);
		when(brother.getId()).thenReturn(NpcID.BARROWS_DHAROK);
		when(brother.getLocalLocation()).thenReturn(new LocalPoint(128, 256));
		WorldView view = mock(WorldView.class);
		when(view.getPlane()).thenReturn(3);
		when(brother.getWorldView()).thenReturn(view);
		when(brother.getCurrentOrientation()).thenReturn(512);
		disguises = new BrotherDisguises(bound -> picks.getAndIncrement() % bound);
		NPCComposition definition = mock(NPCComposition.class);
		when(client.getNpcDefinition(anyInt())).thenReturn(definition);
		when(definition.getModels()).thenReturn(new int[] {123});
		when(definition.getWidthScale()).thenReturn(128);
		when(definition.getHeightScale()).thenReturn(128);
		when(definition.getColorToReplace()).thenReturn(new short[] {10});
		when(definition.getColorToReplaceWith()).thenReturn(new short[] {20});
		original = mock(ModelData.class);
		detached = mock(ModelData.class);
		when(client.loadModelData(123)).thenReturn(original);
		when(original.shallowCopy()).thenReturn(detached);
		when(detached.cloneVertices()).thenReturn(detached);
		when(detached.cloneColors()).thenReturn(detached);
		when(detached.light()).thenReturn(mock(Model.class));
		when(client.createRuneLiteObject()).thenAnswer(invocation -> {
			RuneLiteObject object = mock(RuneLiteObject.class);
			when(object.isActive()).thenReturn(true);
			objects.add(object);
			return object;
		});
	}

	private void refresh() { refreshWithChance(defaults.chanceToRandomize()); }

	private void refreshWithChance(int chance)
	{
		disguises.refresh(client, Collections.singletonList(brother), defaults.npcAnimationMode(), chance);
	}

	@Test
	public void chanceThresholdIsExclusiveAndSkippedSpawnsNeverReroll()
	{
		disguises = new BrotherDisguises(bound -> { picks.incrementAndGet(); return bound == 100 ? 50 : 0; });
		refreshWithChance(50);
		refreshWithChance(100);
		assertEquals(1, picks.get());
		assertFalse(disguises.hides(brother));
		verify(client, never()).getIndexConfig();
		disguises.despawn(brother);
		refreshWithChance(51);
		assertEquals(3, picks.get());
		assertTrue(disguises.hides(brother));
		refreshWithChance(0);
		assertTrue(disguises.hides(brother));
		assertEquals(3, picks.get());
	}

	@Test
	public void zeroChanceDoesNotSampleOrLoadAndClearAllowsNewRoll()
	{
		refreshWithChance(0); refreshWithChance(0);
		assertEquals(0, picks.get());
		assertFalse(disguises.hides(brother));
		verify(client, never()).getIndexConfig();
		disguises.clear();
		refreshWithChance(100);
		assertEquals(1, picks.get());
		assertTrue(disguises.hides(brother));
	}

	@Test
	public void chanceRollSurvivesUnavailableArchiveMetadata()
	{
		disguises = new BrotherDisguises(bound -> { picks.incrementAndGet(); return 0; });
		when(client.getIndexConfig().getFileIds(9)).thenReturn(null);
		refreshWithChance(50); refreshWithChance(0);
		assertEquals(1, picks.get());
		when(client.getIndexConfig().getFileIds(9)).thenReturn(new int[] {NpcID.CHICKEN});
		refreshWithChance(0);
		assertEquals(2, picks.get());
		assertTrue(disguises.hides(brother));
	}

	@Test
	public void restrictsSelectionToTheSixActualBrothers()
	{
		int[] brothers = {NpcID.BARROWS_AHRIM, NpcID.BARROWS_DHAROK, NpcID.BARROWS_GUTHAN,
			NpcID.BARROWS_KARIL, NpcID.BARROWS_TORAG, NpcID.BARROWS_VERAC};
		for (int id : brothers) { assertTrue(BrotherDisguises.isBrother(id)); }
		assertFalse(BrotherDisguises.isBrother(NpcID.BARROWS_SKELETON_ARMED));
		assertFalse(BrotherDisguises.isBrother(NpcID.DT2_DHAROK_COMBAT));
	}

	@Test
	public void picksOnceAndDoesNotRespawnReadyDisguises()
	{
		disguises.spawn(client, brother, defaults.chanceToRandomize());
		refresh(); refresh();
		assertEquals(1, picks.get());
		assertEquals(1, objects.size());
		assertTrue(disguises.hides(brother));
		verify(client).getNpcDefinition(NpcID.CHICKEN);
		verify(objects.get(0)).setLocation(new LocalPoint(128, 256), 3);
		verify(objects.get(0)).setOrientation(512);
		verify(objects.get(0)).setAnimationController(isA(NativeNpcAnimation.class));
		verify(brother, never()).getModel();
	}

	@Test
	public void rerollsOnDespawnAndNewSpawnEvenWhenIndexIsReused()
	{
		refresh();
		disguises.despawn(brother);
		assertFalse(disguises.hides(brother));
		verify(objects.get(0)).setActive(false);
		refresh();
		assertEquals(2, picks.get());
		verify(client).getNpcDefinition(NpcID.COW);
	}

	@Test
	public void missingAssetRetriesTheSameChoiceAndKeepsOriginalVisible()
	{
		when(client.loadModelData(123)).thenReturn(null);
		refresh(); refresh();
		assertFalse(disguises.hides(brother));
		assertEquals(1, picks.get());
		assertTrue(objects.isEmpty());
		when(client.loadModelData(123)).thenReturn(original);
		refresh();
		assertTrue(disguises.hides(brother));
		assertEquals(1, picks.get());
	}

	@Test
	public void registrationFailureDeactivatesStagingAndPreservesOriginal()
	{
		RuneLiteObject object = mock(RuneLiteObject.class);
		when(client.createRuneLiteObject()).thenReturn(object);
		doThrow(new IllegalStateException("full")).when(object).setActive(true);
		refresh();
		assertFalse(disguises.hides(brother));
		verify(object).setActive(false);
	}

	@Test
	public void copiesGeometryAndColoursBeforeChangingSource()
	{
		refresh();
		verify(original).shallowCopy();
		verify(original, never()).recolor(anyShort(), anyShort());
		verify(original, never()).scale(anyInt(), anyInt(), anyInt());
		verify(detached).cloneVertices();
		verify(detached).cloneColors();
		verify(detached).recolor((short) 10, (short) 20);
		verify(detached).scale(128, 128, 128);
	}

	@Test
	public void tracksMovementAndFacingWithoutNewRegistrations()
	{
		refresh();
		when(brother.getLocalLocation()).thenReturn(new LocalPoint(384, 512));
		when(brother.getCurrentOrientation()).thenReturn(1024);
		disguises.move();
		verify(objects.get(0)).setLocation(new LocalPoint(384, 512), 3);
		verify(objects.get(0)).setOrientation(1024);
		assertEquals(1, objects.size());
	}

	@Test
	public void reconciliationAndClearRemoveDisguises()
	{
		refresh();
		disguises.refresh(client, Collections.emptyList(), defaults.npcAnimationMode(), defaults.chanceToRandomize());
		assertFalse(disguises.hides(brother));
		verify(objects.get(0)).setActive(false);
		refresh();
		disguises.clear(); disguises.clear();
		assertFalse(disguises.hides(brother));
		verify(objects.get(1)).setActive(false);
	}

	@Test
	public void samplesEveryAvailableIdIncludingZeroAndSparseHighIdsWithoutFiltering()
	{
		IndexDataBase configs = client.getIndexConfig();
		int[] ids = {0, 90000, NpcID.BARROWS_DHAROK, 42};
		when(configs.getFileIds(9)).thenReturn(ids);
		for (int id : ids)
		{
			refresh();
			verify(client).getNpcDefinition(id);
			disguises.despawn(brother);
		}
		assertEquals(ids.length, picks.get());
		verify(configs).getFileIds(9);
	}

	@Test
	public void waitsForArchiveMetadataThenMakesOneChoice()
	{
		IndexDataBase configs = client.getIndexConfig();
		when(configs.getFileIds(9)).thenReturn(null);
		refresh(); refresh();
		assertEquals(0, picks.get());
		assertFalse(disguises.hides(brother));
		when(configs.getFileIds(9)).thenReturn(new int[] {77777});
		refresh(); refresh();
		verify(client).getNpcDefinition(77777);
		assertEquals(1, picks.get());
		assertTrue(disguises.hides(brother));
	}

	@Test
	public void allModesPreserveSelectionAndRegistration()
	{
		for (NpcAnimationMode mode : NpcAnimationMode.values())
		{
			disguises.refresh(client, Collections.singletonList(brother), mode, defaults.chanceToRandomize());
			disguises.refresh(client, Collections.singletonList(brother), mode, defaults.chanceToRandomize());
			assertTrue(disguises.hides(brother));
		}
		assertEquals(1, picks.get()); assertEquals(1, objects.size());
		verify(objects.get(0)).setAnimationController(isA(NativeNpcAnimation.class));
		verify(objects.get(0)).setActive(true); verify(objects.get(0), never()).setActive(false);
		verify(client).getNpcDefinition(NpcID.CHICKEN);
	}

	@Test
	public void modelLessDefinitionKeepsTheOriginalWithoutRerolling()
	{
		NPCComposition empty = mock(NPCComposition.class);
		when(client.getNpcDefinition(NpcID.CHICKEN)).thenReturn(empty);
		refresh(); refresh();
		assertFalse(disguises.hides(brother));
		assertEquals(1, picks.get());
		assertTrue(objects.isEmpty());
	}

	@Test
	public void resolvesTheChosenDefinitionsCurrentMorph()
	{
		NPCComposition morph = mock(NPCComposition.class);
		NPCComposition child = client.getNpcDefinition(NpcID.COW);
		when(morph.getConfigs()).thenReturn(new int[] {NpcID.COW, -1});
		when(morph.transform()).thenReturn(child);
		when(client.getNpcDefinition(NpcID.CHICKEN)).thenReturn(morph);
		refresh();
		assertTrue(disguises.hides(brother));
		verify(morph).transform();
		assertEquals(1, picks.get());
	}

	@Test
	public void cleanupFailureDoesNotPreventOtherCleanupOrRestoreVisibility()
	{
		NPC second = mock(NPC.class);
		when(second.getId()).thenReturn(NpcID.BARROWS_AHRIM);
		LocalPoint location = brother.getLocalLocation();
		WorldView view = brother.getWorldView();
		when(second.getLocalLocation()).thenReturn(location);
		when(second.getWorldView()).thenReturn(view);
		disguises.refresh(client, java.util.Arrays.asList(brother, second), defaults.npcAnimationMode(), defaults.chanceToRandomize());
		doThrow(new IllegalStateException("cleanup")).when(objects.get(0)).setActive(false);
		disguises.clear();
		verify(objects.get(1)).setActive(false);
		assertFalse(disguises.hides(brother));
		assertFalse(disguises.hides(second));
	}
}

package com.barrowsbrothersrandomizer;

import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.RuneLiteObject;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class NativeNpcAnimationTest
{
	private Client client;
	private IndexDataBase configs;
	private NPC brother;
	private Model base, animated;
	private Animation idle, walk;
	private RuneLiteObject object;
	private final BarrowsBrothersRandomizerConfig defaults = new BarrowsBrothersRandomizerConfig() { };

	@Before
	public void setup()
	{
		client = mock(Client.class);
		configs = mock(IndexDataBase.class);
		when(client.getIndexConfig()).thenReturn(configs);
		when(configs.loadData(9, 77777)).thenReturn(new byte[] {13, 0, 100, 14, 0, 101, 0});
		brother = mock(NPC.class);
		when(brother.getIdlePoseAnimation()).thenReturn(0);
		when(brother.getWalkAnimation()).thenReturn(10);
		when(brother.getAnimation()).thenReturn(999);
		base = mock(Model.class); animated = mock(Model.class);
		idle = animation(100); walk = animation(101);
		when(client.loadAnimation(100)).thenReturn(idle);
		when(client.loadAnimation(101)).thenReturn(walk);
		when(client.applyTransformations(eq(base), any(Animation.class), anyInt(), isNull(), eq(0))).thenReturn(animated);
		object = new RuneLiteObject(client);
		object.setModel(base);
		configured(defaults.npcAnimationMode());
	}

	private Animation animation(int id)
	{
		Animation animation = mock(Animation.class);
		when(animation.getId()).thenReturn(id);
		when(animation.getNumFrames()).thenReturn(3);
		when(animation.getDuration()).thenReturn(3);
		when(animation.getFrameStep()).thenReturn(3);
		when(animation.getFrameLengths()).thenReturn(new int[] {2, 2, 2});
		return animation;
	}

	/** Exercise the same preparation-before-render ordering as the live disguise module. */
	private Model render()
	{
		((NativeNpcAnimation) object.getAnimationController()).prepare();
		return object.getModel();
	}

	private NativeNpcAnimation configured(NpcAnimationMode mode)
	{
		NativeNpcAnimation controller = new NativeNpcAnimation(client, brother, 77777, new AnimationRigCache(client), mode);
		object.setAnimationController(controller);
		return controller;
	}

	private void matchingIdleRigAndDifferentWalkRig()
	{
		IndexDataBase frames = mock(IndexDataBase.class), maps = mock(IndexDataBase.class);
		when(client.getRevision()).thenReturn(240);
		when(client.getIndex(0)).thenReturn(frames); when(client.getIndex(1)).thenReturn(maps);
		when(configs.loadData(12, 100)).thenReturn(AnimationRigCacheTest.sequence(10, 1));
		when(configs.loadData(12, 101)).thenReturn(AnimationRigCacheTest.sequence(30, 1));
		when(configs.loadData(12, 999)).thenReturn(AnimationRigCacheTest.sequence(20, 1));
		when(frames.loadData(10, 0)).thenReturn(new byte[] {0, 7, 1, 1, 64});
		when(frames.loadData(20, 0)).thenReturn(new byte[] {0, 7, 1, 1, 64});
		when(frames.loadData(30, 0)).thenReturn(new byte[] {0, 8, 1, 1, 64});
		when(maps.loadData(7, 0)).thenReturn(new byte[] {1, 1, 1, 0});
		when(maps.loadData(8, 0)).thenReturn(new byte[] {1, 1, 1, 3});
		Animation action = animation(999);
		when(client.loadAnimation(999)).thenReturn(action);
	}

	@Test
	public void playsSelectedNpcsIdleAndDoesNotBorrowBrothersAttack()
	{
		assertSame(animated, render());
		verify(client).applyTransformations(base, idle, 0, null, 0);
		object.tick(3);
		assertSame(animated, render());
		verify(client).applyTransformations(base, idle, 1, null, 0);
		verify(client, never()).loadAnimation(999);
		verify(brother, never()).setAnimation(anyInt());
		verify(brother, never()).setPoseAnimation(anyInt());
		verify(brother, never()).getModel();
		assertSame(base, object.getBaseModel());
	}

	@Test
	public void forcedBrotherActionsUseRealActionFramesThenResumeNativeIdle()
	{
		Animation action = animation(999);
		Model actionModel = mock(Model.class);
		when(client.loadAnimation(999)).thenReturn(action);
		when(brother.getAnimationFrame()).thenReturn(2);
		when(client.applyTransformations(base, action, 2, null, 0)).thenReturn(actionModel);
		configured(NpcAnimationMode.FORCE);
		assertSame(actionModel, render());
		when(brother.getAnimationFrame()).thenReturn(0);
		when(client.applyTransformations(base, action, 0, null, 0)).thenReturn(actionModel);
		assertSame(actionModel, render());
		verify(client).applyTransformations(base, action, 0, null, 0);
		when(brother.getAnimation()).thenReturn(-1);
		assertSame(animated, render());
		verify(client).applyTransformations(base, idle, 0, null, 0);
		verify(brother, never()).setAnimation(anyInt());
	}

	@Test
	public void incompatibleBrotherActionsRetainNativeAnimationWithoutRepeatedExceptions()
	{
		Animation action = animation(999);
		when(client.loadAnimation(999)).thenReturn(action);
		when(client.applyTransformations(base, action, 0, null, 0)).thenThrow(new IllegalArgumentException("rig"));
		configured(NpcAnimationMode.FORCE);
		assertSame(animated, render()); assertSame(animated, render());
		verify(client).applyTransformations(base, action, 0, null, 0);
	}

	@Test
	public void unavailableBrotherActionsRetryOncePerTickAndKeepNativeGait()
	{
		configured(NpcAnimationMode.FORCE);
		assertSame(animated, render()); assertSame(animated, render());
		verify(client).loadAnimation(999);
		when(client.getTickCount()).thenReturn(1);
		Animation action = animation(999);
		when(client.loadAnimation(999)).thenReturn(action);
		assertSame(animated, render());
		verify(client, times(2)).loadAnimation(999);
		verify(client).applyTransformations(base, action, 0, null, 0);
	}

	@Test
	public void autoRequiresRigEvidenceEvenWhenGaitIdsMatchAndNeverDiscoversAssetsDuringRendering()
	{
		when(brother.getIdlePoseAnimation()).thenReturn(100);
		when(brother.getWalkAnimation()).thenReturn(101);
		NativeNpcAnimation controller = configured(NpcAnimationMode.AUTO);
		controller.prepare();
		assertSame(animated, object.getModel());
		verify(client, never()).loadAnimation(999);
		when(client.getRevision()).thenReturn(240);
		when(client.getTickCount()).thenReturn(1);
		controller.prepare();
		clearInvocations(configs, client);
		object.getModel(); object.getModel();
		verify(configs, never()).loadData(anyInt(), anyInt());
		verify(client, never()).loadAnimation(anyInt());
		verify(client, never()).getIndex(anyInt());
		verify(client, never()).getIndexConfig();
	}

	@Test
	public void autoBorrowsOnlyAfterAllClassicFrameMapsMatchAndNativeModeDisablesBorrowing()
	{
		matchingIdleRigAndDifferentWalkRig();
		Animation action = client.loadAnimation(999);
		clearInvocations(client);
		NativeNpcAnimation controller = configured(NpcAnimationMode.AUTO);
		assertSame(animated, render());
		verify(client).applyTransformations(base, action, 0, null, 0);
		controller.options(NpcAnimationMode.NATIVE); controller.prepare();
		clearInvocations(client);
		assertSame(animated, object.getModel());
		verify(client).applyTransformations(base, idle, 0, null, 0);
		verify(client, never()).applyTransformations(eq(base), eq(action), anyInt(), isNull(), eq(0));
	}

	@Test
	public void forceCanBorrowWithoutEvidenceButAutoAndNativeKeepNativeGait()
	{
		Animation action = animation(999); when(client.loadAnimation(999)).thenReturn(action);
		NativeNpcAnimation controller = configured(NpcAnimationMode.FORCE);
		assertSame(animated, render());
		verify(client).applyTransformations(base, action, 0, null, 0);
		for (NpcAnimationMode mode : new NpcAnimationMode[] {NpcAnimationMode.AUTO, NpcAnimationMode.NATIVE})
		{
			controller.options(mode); controller.prepare();
			clearInvocations(client); object.getModel();
			verify(client).applyTransformations(base, idle, 0, null, 0);
			verify(client, never()).applyTransformations(eq(base), eq(action), anyInt(), isNull(), eq(0));
		}
	}

	@Test
	public void formerlyMappedAnimalKeepsNativeGaitWithoutRigEvidence()
	{
		when(brother.getId()).thenReturn(net.runelite.api.gameval.NpcID.BARROWS_KARIL);
		when(brother.getAnimation()).thenReturn(net.runelite.api.gameval.AnimationID.BARROWS_REPEATING_CROSSBOW_FIRE);
		int cow = net.runelite.api.gameval.NpcID.COW;
		when(configs.loadData(9, cow)).thenReturn(new byte[] {13, 0, 100, 14, 0, 101, 0});
